from pathlib import Path
import re

p = Path('src/main.jsx')
s = p.read_text()

new_dash = r'''function Dash({data,month,setMonth}){const[view,setView]=useState('fluxo');return <><div className="dashhead"><div><h1>LookLiP Dash</h1><p>Uma leitura executiva do seu caixa, com foco no que merece atenção.</p></div></div><div className="toolbar dash-toolbar"><MonthSelect month={month} setMonth={setMonth} months={MONTHS}/><div className="dash-switch"><button className={view==='fluxo'?'primary':'ghost'} onClick={()=>setView('fluxo')}>Fluxo</button><button className={view==='budget'?'primary':'ghost'} onClick={()=>setView('budget')}>Budget</button></div></div>{view==='fluxo'?<DashFluxo data={data} month={month}/>:<DashBudget data={data} month={month}/>}</>}
'''

new_fluxo = r'''function DashFluxo({data,month}){const refMonth=month||currentMonth(),months=planningMonths(refMonth,12),rows=months.map(m=>{const f=data.fluxo.find(x=>x.month===m)||{},prest=data.prestadores.filter(x=>x.month===m&&x.ativo!==false),entradas=data.entradas.filter(x=>x.month===m&&x.ativo!==false),despesas=data.despesas.filter(x=>x.month===m&&x.ativo!==false);return {m,...calcFluxoMonth(f,prest,despesas,entradas)}}),current=rows.find(x=>x.m===refMonth)||rows[0],next=rows[1]||current,negative=rows.filter(x=>x.balance<0).length,cumulative=rows.reduce((s,x)=>s+x.balance,0),future=rows.slice(1),avg=future.reduce((s,x)=>s+x.balance,0)/Math.max(1,future.length),commitment=current.entries?current.expenses/current.entries*100:0,best=[...future].sort((a,b)=>b.balance-a.balance)[0]||current,worst=[...future].sort((a,b)=>a.balance-b.balance)[0]||current,trend=next.balance-current.balance,lo=Math.min(0,...rows.map(x=>x.balance)),hi=Math.max(0,...rows.map(x=>x.balance)),span=Math.max(1,hi-lo),point=(v,i)=>`${rows.length===1?50:(i/(rows.length-1))*100},${90-((v-lo)/span)*80}`,zeroY=90-((0-lo)/span)*80;const expenseMap=new Map(),f=data.fluxo.find(x=>x.month===refMonth)||{};FLUXO_FIELDS.forEach(([k,l])=>{const v=Number(f[k]||0);if(v)expenseMap.set(l,v)});data.despesas.filter(x=>x.month===refMonth&&x.ativo!==false).forEach(x=>{const v=Number(x.valor||0);expenseMap.set(x.nome,(expenseMap.get(x.nome)||0)+v)});if(current.employeeTotal)expenseMap.set('Prestadores de Serviço',current.employeeTotal);const top=[...expenseMap.entries()].sort((a,b)=>b[1]-a[1]).slice(0,6),topMax=Math.max(1,...top.map(x=>x[1])),top3=top.slice(0,3).reduce((s,x)=>s+x[1],0),top3Share=current.expenses?top3/current.expenses*100:0;return <div className="dash-content"><div className="kpis"><Kpi t="Saldo do mês" v={current.balance}/><Kpi t="Saldo acumulado" v={cumulative}/><Kpi t="Comprometimento" v={commitment}/><Kpi t="Meses negativos" v={negative} kind="count"/></div><div className="dashboard-grid"><Section title="Evolução do saldo"><div className="dash-chart-meta"><span>Próximos 12 meses</span><strong className={current.balance<0?'negative':''}>{current.m} · {BRL(current.balance)}</strong></div><div className="line-chart"><svg viewBox="0 0 100 100" preserveAspectRatio="none" role="img" aria-label="Evolução projetada do saldo"><line x1="0" x2="100" y1={zeroY} y2={zeroY} className="chart-zero"/><polyline points={rows.map((r,i)=>point(r.balance,i)).join(' ')} className="chart-line" fill="none" vectorEffect="non-scaling-stroke"/>{rows.map((r,i)=>{const[yx,yy]=point(r.balance,i).split(',');return <circle key={r.m} cx={yx} cy={yy} r={r.m===refMonth?'1.8':'1.1'} className={r.m===refMonth?'chart-point current':'chart-point'}><title>{r.m}: {BRL(r.balance)}</title></circle>})}</svg></div><div className="chart-labels">{rows.map(r=><span key={r.m} className={r.m===refMonth?'current':''}>{r.m}</span>)}</div></Section><Section title="Onde o dinheiro está indo"><div className="dash-ranking">{top.map(([name,value],i)=><div key={name}><span><b>{i+1}</b>{name}</span><strong>{BRL(value)}</strong></div>)}</div><div className="dash-share"><span>As 3 maiores despesas representam</span><strong>{top3Share.toFixed(1)}%</strong></div></Section></div><Section title="Leitura executiva"><div className="insight-grid"><div className={current.balance<0?'insight danger':'insight'}><span>Agora</span><b>{current.balance<0?'O mês está no negativo':'O mês fecha positivo'}</b><small>{current.balance<0?'Vale revisar despesas antes de ampliar compromissos.':'Há geração de caixa no mês selecionado.'}</small></div><div className={trend<0?'insight warning':'insight'}><span>Próximo mês</span><b>{trend>=0?'Melhora':'Queda'} de {BRL(Math.abs(trend))}</b><small>{next.m} · comparação com o mês selecionado.</small></div><div className="insight"><span>Maior folga</span><b>{best.m} · {BRL(best.balance)}</b><small>Melhor saldo entre os próximos meses.</small></div><div className={worst.balance<0?'insight danger':'insight'}><span>Ponto de atenção</span><b>{worst.m} · {BRL(worst.balance)}</b><small>{worst.balance<0?'É o pior mês projetado e exige planejamento.':'Ainda positivo, mas é o menor saldo projetado.'}</small></div></div></Section><div className="grid2"><Section title="Pressão das despesas"><div className="pressure"><div><span>Entradas</span><b>{BRL(current.entries)}</b></div><div><span>Despesas</span><b>{BRL(current.expenses)}</b></div><div className="pressure-track"><i style={{width:`${Math.min(100,commitment)}%`}}/></div><small>{commitment.toFixed(1)}% das entradas estão comprometidas neste mês.</small></div></Section><Section title="Sinais do planejamento"><div className="signal-list"><div><span>Saldo médio futuro</span><strong>{BRL(avg)}</strong></div><div><span>Saldo acumulado em 12 meses</span><strong className={cumulative<0?'negative':''}>{BRL(cumulative)}</strong></div><div><span>Concentração nas 3 maiores despesas</span><strong>{top3Share.toFixed(1)}%</strong></div></div></Section></div></div>}
'''

new_budget = r'''function DashBudget({data,month}){const refMonth=month||currentMonth(),months=planningMonths(refMonth,12),calcMonth=m=>{const accounts=data.budgetAccounts.filter(a=>a.month===m&&a.ativo!==false);const budget=accounts.reduce((s,a)=>s+Number(a.budget||0),0);const spent=accounts.reduce((s,a)=>s+data.gastos.filter(g=>g.month===m&&g.budget_account_id===a.id).reduce((x,g)=>x+Number(g.valor||0),0),0);return {m,budget,spent,available:budget-spent}},trend=months.map(calcMonth),current=trend[0]||{budget:0,spent:0,available:0},accounts=data.budgetAccounts.filter(a=>a.month===refMonth&&a.ativo!==false).map(a=>{const spent=data.gastos.filter(g=>g.month===refMonth&&g.budget_account_id===a.id).reduce((s,g)=>s+Number(g.valor||0),0);return {...a,spent,remaining:Number(a.budget||0)-spent,pct:a.budget?spent/a.budget*100:0}}).sort((a,b)=>b.pct-a.pct),over=accounts.filter(a=>a.remaining<0),util=current.budget?current.spent/current.budget*100:0,maxBudget=Math.max(1,...trend.map(x=>Math.max(x.budget,x.spent))),top=accounts[0];return <div className="dash-content"><div className="kpis"><Kpi t="Budget do mês" v={current.budget}/><Kpi t="Realizado" v={current.spent}/><Kpi t="Disponível" v={current.available}/><Kpi t="Utilização" v={util}/></div><div className="dashboard-grid"><Section title="Budget x realizado"><div className="budget-chart">{trend.map(x=><div className="budget-month" key={x.m}><div className="budget-bars"><i style={{height:`${Math.max(4,x.budget/maxBudget*100)}%`}} title={`Budget ${BRL(x.budget)}`}/><b style={{height:`${Math.max(4,Math.min(100,x.spent/maxBudget*100))}%`}} title={`Realizado ${BRL(x.spent)}`}/></div><span>{x.m}</span></div>)}</div><div className="chart-legend"><span><i/>Budget</span><span><b/>Realizado</span></div></Section><Section title="Consumo por conta"><div className="account-bars">{accounts.map(a=><div key={a.id}><div className="account-bar-head"><span>{a.nome}</span><strong className={a.remaining<0?'negative':''}>{a.pct.toFixed(0)}%</strong></div><div className="account-track"><i className={a.remaining<0?'over':''} style={{width:`${Math.min(100,a.pct)}%`}}/></div><small>{BRL(a.spent)} de {BRL(a.budget)}</small></div>)}</div>{!accounts.length&&<div className="empty">Nenhuma conta de budget neste mês.</div>}</Section></div><Section title="Leitura do budget"><div className="insight-grid"><div className={util>100?'insight danger':util>=80?'insight warning':'insight'}><span>Status geral</span><b>{util>100?'Budget estourado':util>=80?'Atenção ao consumo':'Dentro do planejado'}</b><small>{util.toFixed(1)}% do budget mensal já foi utilizado.</small></div><div className={over.length?'insight danger':'insight'}><span>Contas acima do limite</span><b>{over.length} conta(s)</b><small>{over.length?over.map(a=>a.nome).join(' · '):'Nenhuma conta ultrapassou o budget.'}</small></div><div className="insight"><span>Maior consumo</span><b>{top?`${top.nome} · ${top.pct.toFixed(0)}%`:'Sem dados'}</b><small>{top?`${BRL(top.spent)} realizados de ${BRL(top.budget)}.`:'Cadastre um lançamento para começar.'}</small></div><div className="insight"><span>Folga disponível</span><b>{BRL(current.available)}</b><small>Valor que ainda pode ser utilizado sem ultrapassar o budget.</small></div></div></Section></div>}
'''

patterns = [
    (r"function Dash\([\s\S]*?(?=function DashFluxo\()", new_dash),
    (r"function DashFluxo\([\s\S]*?(?=function DashBudget\()", new_fluxo),
    (r"function DashBudget\([\s\S]*?(?=const root=)", new_budget),
]
for pattern, replacement in patterns:
    s, n = re.subn(pattern, replacement, s, count=1)
    if n != 1:
        raise SystemExit(f'Dashboard patch target not found: {pattern}')
p.write_text(s)

css = r'''
/* Dashboard executive insights */
.dash-toolbar{justify-content:space-between;align-items:center}.dash-toolbar .dash-switch{display:flex;gap:6px}.dash-toolbar .dash-switch button{min-width:90px}.dashboard-grid{display:grid;grid-template-columns:1.35fr .85fr;gap:18px;margin-bottom:18px}.dash-chart-meta{display:flex;justify-content:space-between;gap:12px;align-items:center;color:var(--muted);font-size:11px;margin:-2px 0 10px}.dash-chart-meta strong{color:var(--ink);font-size:12px}.line-chart{height:230px;border-bottom:1px solid #e9edf2;background:linear-gradient(to bottom,transparent 49.5%,#f0f2f5 50%,transparent 50.5%);overflow:hidden}.line-chart svg{width:100%;height:100%;display:block;overflow:visible}.chart-line{stroke:var(--blue);stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}.chart-point{fill:#fff;stroke:var(--blue);stroke-width:1.2}.chart-point.current{fill:var(--blue);stroke:#fff;stroke-width:1}.chart-zero{stroke:#cfd5de;stroke-width:.8;stroke-dasharray:2 2}.chart-labels{display:grid;grid-template-columns:repeat(12,1fr);gap:2px;margin-top:8px}.chart-labels span{font-size:8px;color:#8a929e;text-align:center;overflow:hidden;text-overflow:ellipsis}.chart-labels span.current{font-weight:800;color:var(--blue)}.dash-ranking>div{min-height:44px}.dash-ranking strong{font-size:12px;font-variant-numeric:tabular-nums}.dash-share{display:flex;justify-content:space-between;gap:12px;margin-top:10px;padding:12px;background:#f7f9fb;border-radius:10px;color:#697384;font-size:11px}.dash-share strong{color:var(--ink);font-size:13px}.insight-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.insight{border:1px solid #e9edf2;background:#fbfcfd;border-radius:13px;padding:14px;min-height:122px}.insight>span{display:block;color:#8a929e;font-size:9px;text-transform:uppercase;letter-spacing:.08em;margin-bottom:7px}.insight>b{display:block;font-size:13px;line-height:1.3}.insight small{display:block;margin-top:7px;color:#697384;font-size:10px;line-height:1.4}.insight.warning{border-color:#f0dfbd;background:#fffaf1}.insight.danger{border-color:#f1cccc;background:#fff7f7}.pressure>div:not(.pressure-track){display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #eef1f4;font-size:12px}.pressure-track{height:12px;background:#edf0f3;border-radius:999px;overflow:hidden;margin:16px 0 9px}.pressure-track i{display:block;height:100%;background:var(--warning);border-radius:999px}.pressure small{color:#7b8491;font-size:10px}.signal-list>div{display:flex;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid #eef1f4;font-size:11px}.signal-list>div:last-child{border-bottom:0}.signal-list span{color:#697384}.signal-list strong{font-variant-numeric:tabular-nums}.budget-chart{height:220px;display:flex;align-items:end;gap:6px;border-bottom:1px solid #e9edf2;padding:8px 2px 0}.budget-month{height:100%;flex:1;display:flex;flex-direction:column;justify-content:end;align-items:center;gap:6px;min-width:0}.budget-bars{height:190px;width:100%;display:flex;align-items:end;justify-content:center;gap:3px}.budget-bars i,.budget-bars b{display:block;width:9px;border-radius:5px 5px 1px 1px;min-height:4px}.budget-bars i{background:#cfd8e7}.budget-bars b{background:var(--blue)}.budget-month>span{font-size:8px;color:#8a929e;white-space:nowrap}.chart-legend{display:flex;gap:16px;margin-top:10px;font-size:10px;color:#697384}.chart-legend span{display:flex;align-items:center;gap:6px}.chart-legend i,.chart-legend b{display:block;width:10px;height:10px;border-radius:3px;background:#cfd8e7}.chart-legend b{background:var(--blue)}.account-bars>div{margin-bottom:14px}.account-bar-head{display:flex;justify-content:space-between;gap:10px;font-size:11px;margin-bottom:5px}.account-bar-head strong{font-variant-numeric:tabular-nums}.account-track{height:10px;background:#eef1f4;border-radius:999px;overflow:hidden}.account-track i{display:block;height:100%;background:var(--blue);border-radius:999px}.account-track i.over{background:var(--danger)}.account-bars small{display:block;color:#8a929e;font-size:9px;margin-top:4px}.dash-content>.card{margin-bottom:18px}
@media(max-width:800px){.dashboard-grid{grid-template-columns:1fr}.insight-grid{grid-template-columns:1fr 1fr}.line-chart{height:190px}.budget-chart{height:190px}.budget-bars{height:160px}.dash-toolbar{align-items:stretch;gap:10px}.dash-toolbar .dash-switch{width:100%}.dash-toolbar .dash-switch button{flex:1}}
@media(max-width:520px){.dashhead h1{font-size:24px}.dash-toolbar{flex-direction:column}.dash-toolbar>label{justify-content:space-between}.insight-grid{grid-template-columns:1fr}.chart-labels span{font-size:7px}.line-chart{height:170px}.budget-chart{height:175px}.budget-bars{height:145px}.budget-bars i,.budget-bars b{width:7px}.dashboard-grid{gap:12px}}
'''
sp=Path('src/styles.css')
ss=sp.read_text()
marker='/* Dashboard executive insights */'
if marker not in ss:
    sp.write_text(ss+'\n'+css)
else:
    print('Dashboard CSS already present')
print('Dashboard insights patch applied')
